INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "幽州军民迎李克用入府舍", "start_year": 895, "end_year": 895, "time_original": "895年春正月辛酉", "dynasty": "唐", "description": "幽州军民数万以麾盖、歌鼓迎李克用进入府舍。", "phases": [], "location_name": "幽州、府舍", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6b36668f-c7a7-5c72-a9d9-05803377a307"}, {"title": "李克用命李存审刘仁恭略定巡属", "start_year": 895, "end_year": 895, "time_original": "895年正月辛酉条；具体起讫未载", "dynasty": "唐", "description": "李克用命李存审、刘仁恭带兵平定幽州所辖地区。", "phases": [], "location_name": "幽州巡属", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bf5ef104-2086-5bae-86b7-0d8ab089b01b"}, {"title": "朱全忠遣朱友恭围兗州", "start_year": 895, "end_year": 895, "time_original": "895年正月癸未", "dynasty": "唐", "description": "朱全忠派朱友恭包围兗州。", "phases": [], "location_name": "兗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2dae4437-d0da-5007-ac93-a6d4f4e37757"}, {"title": "朱瑄援兗粮兵遭高梧伏击，安氏两将被俘", "start_year": 895, "end_year": 895, "time_original": "895年正月条；围兗以后，确日未载", "dynasty": "唐", "description": "朱瑄从郓州率兵带粮救兗，朱友恭设伏，在高梧击败援军，夺其全部军粮，俘河东将安福顺、安福庆。", "phases": [], "location_name": "高梧、兗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "610ab270-9af5-5e50-a23a-f1d7cf8d61c4"}, {"title": "陆希声授户部侍郎同平章事", "start_year": 895, "end_year": 895, "time_original": "895年正月己已；底本日字如此", "dynasty": "唐", "description": "朝廷以给事中陆希声为户部侍郎、同平章事。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "857bb1ad-c496-5ee3-a018-dec80b017020"}, {"title": "护国节度使王重盈卒", "start_year": 895, "end_year": 895, "time_original": "895年正月壬申", "dynasty": "唐", "description": "护国节度使王重盈去世。", "phases": [], "location_name": "护国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bc81234c-49dc-559c-b2d3-db7e149a1a32"}, {"title": "军中请王珂知留后事", "start_year": 895, "end_year": 895, "time_original": "895年正月壬申条；重盈卒后", "dynasty": "唐", "description": "王重盈死后，军中请求以王重荣之养子、行军司马王珂暂管留后事务。", "phases": [], "location_name": "护国、河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4323b6ee-b187-596d-868e-20ccd28f9cf7"}, {"title": "杨行密表朱全忠罪恶，请会四方兵讨之", "start_year": 895, "end_year": 895, "time_original": "895年正月条；具体日未载", "dynasty": "唐", "description": "杨行密上表指述朱全忠罪恶，请求会合易定、兗、郓、河东军讨伐。", "phases": [], "location_name": "朝廷、易定、兗郓、河东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ad59504e-3bf7-58a6-a625-749d213c31d1"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

